/* re:poem — 模块 05 的七张底图
   为了能导出 PNG，底图必须是 data: URL —— file:// 下把本地图片画进 canvas
   会把画布"污染"，toDataURL() 直接抛 SecurityError。这张表同时供 CSS 预览
   和 canvas 导出使用，两处像素同源，所见即所得。 */

RePoem.module('bgs', function () {
  'use strict';
  return {
  1: 'data:image/jpeg;base64,',
  2: 'data:image/jpeg;base64,',
  3: 'data:image/jpeg;base64,',
  4: 'data:image/jpeg;base64,',
  5: 'data:image/jpeg;base64,',
  6: 'data:image/jpeg;base64,',
  7: 'data:image/jpeg;base64,'
  };
});
